/* * header file to be used with term.c.  defines some macros to place the * cursor in various places on the screen. * * Larry Moss (lm03_cif@uhura.cc.rochester.edu) */#define putp(str)	tputs(str, 0, outc)#define HAS_CAP(str)	(*str)#define clrdisp()	tputs(clear_screen, Lines, outc)#define home()		putp(cursor_home)#define gotoxy(c, l)	putp(tgoto(cursor_address, c, l))#define SP ' '